macro_rules! deps {
    () => {
        CallOffset!();
        Encoding!();
        Name!();
        ResourceName!();
    };
}

macro_rules! SpecialName {
    () => {
        deps!();
        # [doc = " The `<special-name>` production."] # [doc = ""] # [doc = " The `<special-name>` production is spread in pieces through out the ABI"] # [doc = " spec, and then there are a bunch of `g++` extensions that have become de"] # [doc = " facto."] # [doc = ""] # [doc = " ### 5.1.4.1 Virtual Tables and RTTI"] # [doc = ""] # [doc = " ```text"] # [doc = " <special-name> ::= TV <type>    # virtual table"] # [doc = "                ::= TT <type>    # VTT structure (construction vtable index)"] # [doc = "                ::= TI <type>    # typeinfo structure"] # [doc = "                ::= TS <type>    # typeinfo name (null-terminated byte string)"] # [doc = " ```"] # [doc = ""] # [doc = " ### 5.1.4.2 Virtual Override Thunks"] # [doc = ""] # [doc = " ```text"] # [doc = " <special-name> ::= T <call-offset> <base encoding>"] # [doc = "     # base is the nominal target function of thunk"] # [doc = ""] # [doc = " <special-name> ::= Tc <call-offset> <call-offset> <base encoding>"] # [doc = "     # base is the nominal target function of thunk"] # [doc = "     # first call-offset is 'this' adjustment"] # [doc = "     # second call-offset is result adjustment"] # [doc = " ```"] # [doc = ""] # [doc = " ### 5.1.4.4 Guard Variables"] # [doc = ""] # [doc = " ```text"] # [doc = " <special-name> ::= GV <object name> # Guard variable for one-time initialization"] # [doc = "     # No <type>"] # [doc = " ```"] # [doc = ""] # [doc = " ### 5.1.4.5 Lifetime-Extended Temporaries"] # [doc = ""] # [doc = " ```text"] # [doc = " <special-name> ::= GR <object name> _             # First temporary"] # [doc = " <special-name> ::= GR <object name> <seq-id> _    # Subsequent temporaries"] # [doc = " ```"] # [doc = ""] # [doc = " ### De Facto Standard Extensions"] # [doc = ""] # [doc = " ```text"] # [doc = " <special-name> ::= TC <type> <number> _ <type>    # construction vtable"] # [doc = "                ::= TF <type>                      # typinfo function"] # [doc = "                ::= TH <name>                      # TLS initialization function"] # [doc = "                ::= TW <name>                      # TLS wrapper function"] # [doc = "                ::= Gr <resource name>             # Java Resource"] # [doc = "                ::= GTt <encoding>                 # Transaction-Safe function"] # [doc = "                ::= GTn <encoding>                 # Non-Transaction-Safe function"] # [doc = " ```"] # [derive (Clone , Debug , PartialEq , Eq)] pub enum SpecialName { # [doc = " A virtual table."] VirtualTable (TypeHandle) , # [doc = " A VTT structure (construction vtable index)."] Vtt (TypeHandle) , # [doc = " A typeinfo structure."] Typeinfo (TypeHandle) , # [doc = " A typeinfo name (null-terminated byte string)."] TypeinfoName (TypeHandle) , # [doc = " A virtual override thunk."] VirtualOverrideThunk (CallOffset , Box < Encoding >) , # [doc = " A virtual override thunk with a covariant return type."] VirtualOverrideThunkCovariant (CallOffset , CallOffset , Box < Encoding >) , # [doc = " An initialization guard for some static storage."] Guard (Name) , # [doc = " A temporary used in the initialization of a static storage and promoted"] # [doc = " to a static lifetime."] GuardTemporary (Name , usize) , # [doc = " A construction vtable structure."] ConstructionVtable (TypeHandle , usize , TypeHandle) , # [doc = " A typeinfo function."] TypeinfoFunction (TypeHandle) , # [doc = " A TLS initialization function."] TlsInit (Name) , # [doc = " A TLS wrapper function."] TlsWrapper (Name) , # [doc = " A Java Resource."] JavaResource (Vec < ResourceName >) , # [doc = " A function declared transaction-safe"] TransactionClone (Box < Encoding >) , # [doc = " A function declared non-transaction-safe"] NonTransactionClone (Box < Encoding >) , }
    };
}

SpecialName!()